{"path":"/root/solve_workbook.py","content":"import os
import re
import openpyxl
from openpyxl.utils import get_column_letter

input_path = '/root/data/workbook.xlsx'
output_path = '/root/output/result.xlsx'
os.makedirs('/root/output', exist_ok=True)

wb = openpyxl.load_workbook(input_path, data_only=False)
print('Sheet names:', wb.sheetnames)

ts = wb['Task']
print('Row 10 (headers):', [ts.cell(r, c).value for r, c in [(10, col) for col in range(1, 15)]])
print('Row 11 (sub-headers):', [ts.cell(11, c).value for c in range(1, 15)])
for r in range(12, 48):
    print(f'Row {r}:', [ts.cell(r, c).value for c in range(1, 15)])
print('Row 50:', [ts.cell(50, c).value for c in range(1, 15)])

ds = wb['Data']
for r in range(1, 5):
    print(f'Data row {r}:', [ds.cell(r, c).value for c in range(1, 20)])
for r in range(19, 42):
    print(f'Data row {r}:', [ds.cell(r, c).value for c in range(1, 20)])

# Detect Data column containing series codes by matching Task!D lookup codes.
lookup_rows = list(range(12, 18)) + list(range(19, 25)) + list(range(26, 32))
task_codes = [ts.cell(r, 4).value for r in lookup_rows if ts.cell(r, 4).value is not None]
code_scores = {}
for c in range(1, 20):
    data_values = {ds.cell(r, c).value for r in range(21, 39)}
    code_scores[c] = sum(1 for code in task_codes if code in data_values)
series_code_col = max(code_scores, key=code_scores.get)
if code_scores[series_code_col] == 0:
    raise RuntimeError(f'Could not locate Data series-code column. Scores: {code_scores}')

# Detect Data row containing years by matching Task!H10:L10.
task_years = [ts.cell(10, c).value for c in range(8, 13) if ts.cell(10, c).value is not None]
year_scores = {}
for r in range(1, 42):
    row_values = {ds.cell(r, c).value for c in range(1, 20)}
    year_scores[r] = sum(1 for year in task_years if year in row_values)
year_header_row = max(year_scores, key=year_scores.get)
if year_scores[year_header_row] == 0:
    raise RuntimeError(f'Could not locate Data year header row. Scores: {year_scores}')

year_cols = [c for c in range(1, 20) if ds.cell(year_header_row, c).value in set(task_years)]
if not year_cols:
    raise RuntimeError('Could not locate year columns on Data sheet')
first_year_col, last_year_col = min(year_cols), max(year_cols)

print('Detected Data series-code column:', get_column_letter(series_code_col), 'score:', code_scores[series_code_col])
print('Detected Data year header row:', year_header_row, 'score:', year_scores[year_header_row])
print('Detected Data year columns:', get_column_letter(first_year_col), 'through', get_column_letter(last_year_col))

# Show block labels from nearby rows/columns to document assignment.
for label_row in [11, 18, 25, 34, 41, 50]:
    print(f'Task label/context row {label_row}:', [ts.cell(label_row, c).value for c in range(1, 14)])

# Map lookup blocks to their metric labels. We inspect text near each block, with
# a conservative fallback to the row order stated in the prompt.
def normalize_text(value):
    return '' if value is None else re.sub(r'[^a-z0-9]+', ' ', str(value).lower()).strip()

def block_context(start_row):
    rows = range(max(1, start_row - 2), min(ts.max_row, start_row + 6) + 1)
    vals = []
    for r in rows:
        for c in range(1, 8):
            v = ts.cell(r, c).value
            if v is not None:
                vals.append(str(v))
    return ' | '.join(vals)

block_starts = [12, 19, 26]
contexts = {start: block_context(start) for start in block_starts}
for start, ctx in contexts.items():
    print(f'Lookup block starting row {start} context:', ctx)

metric_keywords = {
    'finished': ['finished output', 'finished'],
    'scrap': ['scrap and rework', 'scrap', 'rework'],
    'capacity': ['rated production capacity', 'rated', 'capacity'],
}
assignments = {}
remaining = set(block_starts)
for metric, keywords in metric_keywords.items():
    hits = []
    for start in block_starts:
        ctx_norm = normalize_text(contexts[start])
        score = sum(1 for kw in keywords if normalize_text(kw) in ctx_norm)
        if score:
            hits.append((score, start))
    if hits:
        hits.sort(reverse=True)
        assignments[metric] = hits[0][1]
        remaining.discard(hits[0][1])

# Fallback order from the task if any label is not machine-detected.
fallback = {'finished': 12, 'scrap': 19, 'capacity': 26}
for metric, start in fallback.items():
    assignments.setdefault(metric, start)
print('Metric block assignments:', assignments)

code_col_letter = get_column_letter(series_code_col)
first_year_col_letter = get_column_letter(first_year_col)
last_year_col_letter = get_column_letter(last_year_col)
index_range = f"Data!${first_year_col_letter}$21:${last_year_col_letter}$38"
match_code_range = f"Data!${code_col_letter}$21:${code_col_letter}$38"
match_year_range = f"Data!${first_year_col_letter}${year_header_row}:${last_year_col_letter}${year_header_row}"
print('Formula ranges:', index_range, match_code_range, match_year_range)

# Step 1: write lookup formulas in the yellow lookup cells.
for start_row in block_starts:
    for r in range(start_row, start_row + 6):
        for c in range(8, 13):
            col = get_column_letter(c)
            ts.cell(r, c).value = f'=INDEX({index_range}, MATCH($D{r},{match_code_range},0), MATCH({col}$10,{match_year_range},0))'

# Step 2: derived formulas for net production slack in H35:L40.
finished_start = assignments['finished']
scrap_start = assignments['scrap']
capacity_start = assignments['capacity']
for i, r in enumerate(range(35, 41)):
    for c in range(8, 13):
        col = get_column_letter(c)
        finished_cell = f'{col}{finished_start + i}'
        scrap_cell = f'{col}{scrap_start + i}'
        capacity_cell = f'{col}{capacity_start + i}'
        ts.cell(r, c).value = f'=({finished_cell}-{scrap_cell})/{capacity_cell}*100'

# Step 3: summary statistics. Confirm labels and then write in requested rows.
for r in range(42, 48):
    print(f'Summary label row {r}:', [ts.cell(r, c).value for c in range(1, 8)])
summary_formulas = {
    42: 'MIN',
    43: 'MAX',
    44: 'MEDIAN',
    45: 'AVERAGE',
}
for c in range(8, 13):
    col = get_column_letter(c)
    data_range = f'{col}35:{col}40'
    for r, func in summary_formulas.items():
        ts.cell(r, c).value = f'={func}({data_range})'
    ts.cell(46, c).value = f'=_xlfn.PERCENTILE.INC({data_range},0.25)'
    ts.cell(47, c).value = f'=_xlfn.PERCENTILE.INC({data_range},0.75)'

# Step 4: weighted mean, weighted by Rated Production Capacity block.
for c in range(8, 13):
    col = get_column_letter(c)
    ts.cell(50, c).value = f'=SUMPRODUCT({col}35:{col}40,{col}{capacity_start}:{col}{capacity_start + 5})/SUM({col}{capacity_start}:{col}{capacity_start + 5})'

# Ensure no new sheets were added and save.
print('Sheet names before save:', wb.sheetnames)
wb.save(output_path)
print('Saved workbook:', output_path)

# Step 6: verify formulas were written.
wb2 = openpyxl.load_workbook(output_path, data_only=False)
ts2 = wb2['Task']
print('Sheet names after reload:', wb2.sheetnames)
for r in [12, 19, 26, 35, 42, 46, 47, 50]:
    print(f'Row {r}:', [ts2.cell(r, c).value for c in range(8, 13)])

# Additional guard for the critical percentile prefix.
for r in [46, 47]:
    for c in range(8, 13):
        v = ts2.cell(r, c).value
        if not (isinstance(v, str) and v.startswith('=_xlfn.PERCENTILE.INC(')):
            raise RuntimeError(f'Missing required _xlfn prefix in {get_column_letter(c)}{r}: {v!r}')
print('Verification passed: formulas written and percentile prefix retained.')
